<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\User\Domain\UserRef;
use Civi\Lughauth\Features\Access\UserInvitation\Domain\ValueObject\Accessor\UserInvitationInvitedByAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the UserInvitationInvitedByAccessor trait.
 *
 * Covers null default, string/VO assignment via withInvitedBy,
 * getInvitedBy/invitedBy accessors, and isInvitedByChanged with/without original.
 */
class UserInvitationInvitedByAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withInvitedBy creates a new instance with the InvitedBy set
     * from a string value, and getInvitedBy returns the primitive string.
     */
    public function testWithInvitedByFromString(): void
    {
        // Arrange
        $holder = new ImplWithUserInvitationInvitedByAccessorUnitTest();

        // Act
        $result = $holder->withInvitedBy(new UserRef('one'));

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals(new UserRef('one'), $result->getInvitedBy());
    }
    /**
     * Asserts that withinvitedBy has access to the value object
     * from a string value, and getInvitedBy returns the primitive string.
     */
    public function testWithInvitedByFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithUserInvitationInvitedByAccessorUnitTest();

        // Act
        $result = $holder->withInvitedBy(new UserRef('one'));

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals(new UserRef('one'), $result->invitedBy()->value());
    }
    public function testChangedInvitedBy(): void
    {
        // Arrange
        $holder = new ImplWithUserInvitationInvitedByAccessorUnitTest()->withInvitedBy(new UserRef('one'));
        $original = $holder->withInvitedBy(new UserRef('one'));
        $same = $holder->withInvitedBy(new UserRef('one'));
        $modified = $holder->withInvitedBy(new UserRef('other'));

        // Act
        $withSame = $original->isInvitedByChanged($same);
        $withDiferent = $original->isInvitedByChanged($modified);

        // Assert
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithUserInvitationInvitedByAccessorUnitTest
{
    use UserInvitationInvitedByAccessor;
}
